import 'package:flutter/material.dart'; import '../../services/auth_service.dart'; import '../../repositories/certificate_repository.dart'; import '../../widgets/certificate_card.dart'; class CertificatesPage extends StatelessWidget { const CertificatesPage({super.key}); @override Widget build(BuildContext c){final id=AuthService().currentUser?.uid??'';return Scaffold(appBar:AppBar(title:const Text('شهاداتي')),body:StreamBuilder(stream:CertificateRepository().byStudent(id),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());if(s.data!.isEmpty)return const Center(child:Text('لا توجد شهادات بعد'));return ListView(children:s.data!.map((x)=>CertificateCard(certificate:x)).toList());}));}}